1	import type { Actor, Role } from "@/types/member";
2	import { ROLE_RANK } from "@/types/member";
3	import type {
4	  PermissionAction,
5	  PermissionDecision,
6	  PermissionResource,
7	} from "@/types/permission";
8	
9	/**
10	 * The single authorization entry point for Taskflow.
11	 *
12	 * Every Server Action, service method, Route Handler and permission-sensitive
13	 * UI component funnels through `can()`. Nothing else may branch on
14	 * `actor.role` directly — if you find yourself writing `role === "admin"`,
15	 * add an action to `PermissionAction` and a row to `ROLE_MATRIX` instead.
16	 *
17	 * Decision order:
18	 *   1. cross-tenant guard (`actor.orgId` must equal `resource.orgId`)
19	 *   2. platform staff bypass
20	 *   3. role matrix lookup
21	 *   4. ownership escalations (authors edit their own issues/comments)
22	 */
23	
24	/** Minimum role required for each action, before ownership escalations. */
25	export const ROLE_MATRIX: Readonly<Record<PermissionAction, Role>> = {
26	  "org:read": "viewer",
27	  "org:update": "admin",
28	  "org:delete": "owner",
29	  "org:manage_billing": "owner",
30	  "org:manage_flags": "admin",
31	  "member:read": "viewer",
32	  "member:invite": "admin",
33	  "member:update_role": "admin",
34	  "member:remove": "admin",
35	  "project:create": "member",
36	  "project:read": "viewer",
37	  "project:update": "member",
38	  "project:archive": "admin",
39	  "project:delete": "owner",
40	  "issue:create": "member",
41	  "issue:read": "viewer",
42	  "issue:update": "member",
43	  "issue:assign": "member",
44	  "issue:archive": "member",
45	  "issue:delete": "admin",
46	  "comment:create": "member",
47	  "comment:read": "viewer",
48	  "comment:update": "member",
49	  "comment:delete": "admin",
50	  "activity:read": "member",
51	  "activity:export": "admin",
52	  "notification:read": "viewer",
53	  "notification:manage": "viewer",
54	  "webhook:manage": "admin",
55	};
56	
57	/** Actions an actor may perform on their own content regardless of role rank. */
58	const OWNERSHIP_ESCALATIONS: Readonly<Partial<Record<PermissionAction, true>>> = {
59	  "issue:update": true,
60	  "issue:archive": true,
61	  "comment:update": true,
62	  "comment:delete": true,
63	  "notification:manage": true,
64	};
65	
66	function isOwnedByActor(
67	  actor: Actor,
68	  resource: PermissionResource,
69	): boolean {
70	  switch (resource.kind) {
71	    case "issue":
72	      return (
73	        resource.authorId === actor.userId ||
74	        resource.assigneeId === actor.userId
75	      );
76	    case "comment":
77	      return resource.authorId === actor.userId;
78	    case "project":
79	      return resource.leadId === actor.userId;
80	    case "notification":
81	      return resource.recipientId === actor.userId;
82	    case "member":
83	      return resource.targetUserId === actor.userId;
84	    default:
85	      return false;
86	  }
87	}
88	
89	/**
90	 * Answers "may this actor perform this action on this resource?".
91	 *
92	 * @param actor    the authenticated principal, always scoped to one org
93	 * @param action   a member of the closed `PermissionAction` vocabulary
94	 * @param resource the object being acted on, discriminated on `kind`
95	 */
96	export function can(
97	  actor: Actor,
98	  action: PermissionAction,
99	  resource: PermissionResource,
100	): boolean {
101	  return explain(actor, action, resource).allowed;
102	}
103	
104	/** Same decision as `can()`, but reports why — used by the settings UI. */
105	export function explain(
106	  actor: Actor,
107	  action: PermissionAction,
108	  resource: PermissionResource,
109	): PermissionDecision {
110	  const base = { action, resourceKind: resource.kind } as const;
111	
112	  if (actor.orgId !== resource.orgId) {
113	    return { ...base, allowed: false, reason: "denied_cross_tenant" };
114	  }
115	
116	  if (actor.isPlatformStaff === true) {
117	    return { ...base, allowed: true, reason: "granted_by_staff" };
118	  }
119	
120	  const required = ROLE_MATRIX[action];
121	  if (required === undefined) {
122	    return { ...base, allowed: false, reason: "denied_unknown_action" };
123	  }
124	
125	  if (ROLE_RANK[actor.role] >= ROLE_RANK[required]) {
126	    return { ...base, allowed: true, reason: "granted_by_role" };
127	  }
128	
129	  if (OWNERSHIP_ESCALATIONS[action] === true && isOwnedByActor(actor, resource)) {
130	    return { ...base, allowed: true, reason: "granted_by_ownership" };
131	  }
132	
133	  return { ...base, allowed: false, reason: "denied_by_role" };
134	}
135	
136	/** Thrown by `assertCan()`; mapped to a `forbidden` `ActionResult` by callers. */
137	export class PermissionDeniedError extends Error {
138	  readonly code = "forbidden" as const;
139	
140	  constructor(
141	    readonly action: PermissionAction,
142	    readonly decision: PermissionDecision,
143	  ) {
144	    super(`Permission denied: ${action} on ${decision.resourceKind}`);
145	    this.name = "PermissionDeniedError";
146	  }
147	}
148	
149	/** Throwing variant of `can()` for service-layer guard clauses. */
150	export function assertCan(
151	  actor: Actor,
152	  action: PermissionAction,
153	  resource: PermissionResource,
154	): void {
155	  const decision = explain(actor, action, resource);
156	  if (!decision.allowed) {
157	    throw new PermissionDeniedError(action, decision);
158	  }
159	}
160	
161	/** Bulk evaluation used by navigation and toolbar components. */
162	export function canAll(
163	  actor: Actor,
164	  actions: readonly PermissionAction[],
165	  resource: PermissionResource,
166	): boolean {
167	  return actions.every((action) => can(actor, action, resource));
168	}
